#include <stdint.h>
#include <stdio.h>




int main(void)
{
	uint32_t *SysClockEnable = (uint32_t*)0x40023830;

	uint32_t *GpioAModer = (uint32_t*)0x40020000;
	uint32_t *GpioAInputdataReg = (uint32_t*)0x40020010;

	uint32_t *GpioDModer = (uint32_t*)0x40020c00;
	uint32_t *GpioDOutputdataReg = (uint32_t*)0x40020c14;

   *SysClockEnable |= 0x00000009;
   *GpioAModer 	   &= ~(3<<0);
   // Setting GPIO D Mode 24 Nd 25 th bit Zero and Setting 24 th bit as high
   *GpioDModer	   &= ~(3<<24);
   *GpioDModer     |= (1<<24);

   while(1)
   {


	   uint8_t pinStatus = (uint8_t)(*GpioAInputdataReg & 0x01);



	   if (pinStatus)
	   {
		   *GpioDOutputdataReg |= (1<<12);

	   }
	   else
	   {
		   *GpioDOutputdataReg &= ~(1<<12);
	   }
   }


	return 0;
}
